//! 🎛️ One authenticated failure frontier preserves its actual capsule and every receipt until handback.
use super::{ActorFailureHome,ActorFailurePermit,ActorFailureSealed,ActorFailureCapsule,ActorFailureRecipient,ActorFailureRecipientHome,ActorFailureRecipientAccepted,pay_many,refused};
use semio_framework_actor::{ActorFailureCallKind,ActorFailureCallReference};
