#[derive(Clone,Copy,PartialEq,Eq)]enum Phase{Empty,Publish,Prepare,Read,Borrow,ChunkAck,Seal,Deliver,Recipient,Ack,Complete,Closed}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum ActorFailureFetchStatus{Empty,Action,Frozen,PrepareFault,Page,SealFault,FinishSeal,Deliver,Recipient,Complete,Closed}
/// 🧭️ Borrow6 inserts actual operation/generation between the first and final pair; it has no guest subloan.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct ActorFailurePlan{pub kind:ActorFailureCallKind,pub prefix:[u64;4],pub prefix_length:usize,pub scoped:bool}
fn plan(kind:ActorFailureCallKind,reference:ActorFailureCallReference,offset:usize,length:usize)->ActorFailurePlan{let page=matches!(kind,ActorFailureCallKind::BorrowActorFailure|ActorFailureCallKind::AcknowledgeActorFailureChunk);ActorFailurePlan{kind,prefix:[reference.failed_epoch,reference.call_kind.tag(),offset as u64,length as u64],prefix_length:if page{4}else{2},scoped:kind!=ActorFailureCallKind::BorrowActorFailure}}
/// ✅️ The real recipient and actual final guest header handback jointly authorize cleanup-only continuation.
pub struct ActorFailureAcknowledged{proof:GuestActorFailureAcknowledged}
impl ActorFailureAcknowledged{pub fn host_proof(&self)->&GuestActorFailureAcknowledged{&self.proof}pub fn proves(&self,reference:&GuestActorFailureCallReference,producer:OriginalNativeRecipientIdentity,cx:&StepContext<'_>)->Result<bool,OriginalTurnFailure>{Ok(reference.reference_for(producer,cx)?==self.proof.reference_for(producer,cx)?)}pub fn runtime_proof(&self)->&semio_plugin_host_guest_runtime::OwnedActorFailureAcknowledged{self.proof.runtime_proof()}}
/// 🧳️ Admission owns this whole fixed header, donor and lease before the failure route starts.
pub struct ActorFailureFetch{reference:Option<GuestActorFailureCallReference>,permit:Option<ActorFailurePermit>,phase:Phase,header:[u8;184],header_cursor:usize,identity:Option<GuestFrozenEscrowIdentity>,captured:Option<ActorFailureCall>,settled:bool,total:usize,offset:usize,page:usize,cursor:usize,sealed:Option<ActorFailureSealed>,capsule:Option<ActorFailureCapsule>,donor:Option<ActorFailureRecipientHome>,acquired:bool,returned:bool,accepted:Option<ActorFailureRecipientAccepted>,acknowledged:Option<ActorFailureAcknowledged>,home:usize}
impl ActorFailureFetch{pub const fn empty()->Self{Self{reference:None,permit:None,phase:Phase::Empty,header:[0;184],header_cursor:0,identity:None,captured:None,settled:false,total:0,offset:0,page:0,cursor:0,sealed:None,capsule:None,donor:None,acquired:false,returned:false,accepted:None,acknowledged:None,home:0}}
 pub fn bind_step<T:OriginalNativeRetirement>(mut producer:OriginalNativeBorrowed<'_,T>,project:impl for<'a>FnOnce(&'a mut T)->Result<(&'a mut Self,&'a mut Option<GuestActorFailureCallReference>),OriginalTurnFailure>,fault:&Option<OriginalNativeLease<ActorFailureHome>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{producer.validate_context(cx)?;let identity=producer.recipient_identity();let(fetch,reference)=project(producer.value_mut())?;if fetch.phase!=Phase::Empty{return Err(refused().into())}let reference_value=reference.as_ref().ok_or_else(refused)?.reference_for(identity,cx)?;let recipient=fault.as_ref().ok_or_else(refused)?.recipient_identity();recipient.validate_context(cx)?;let bytes=size_of::<Option<GuestActorFailureCallReference>>()*2+size_of::<Option<ActorFailurePermit>>()+size_of::<Phase>()+size_of::<usize>();if !pay_many(cx,5,bytes,0)?{return Ok(false)}fetch.home=fetch as*const Self as usize;fetch.reference=reference.take();fetch.permit=Some(ActorFailurePermit{recipient,producer:identity,reference:reference_value,binding:OriginalSourceBinding::borrow(cx)});fetch.phase=Phase::Publish;Ok(true)}
 fn permit(&self,cx:&StepContext<'_>)->Result<&ActorFailurePermit,OriginalTurnFailure>{let permit=self.permit.as_ref().ok_or_else(refused)?;if self.home!=self as*const Self as usize||!permit.proves(permit.recipient,cx)||self.reference.as_ref().ok_or_else(refused)?.reference_for(permit.producer,cx)?!=permit.reference{return Err(refused().into())}Ok(permit)}
 pub fn status(&self,cx:&StepContext<'_>)->Result<ActorFailureFetchStatus,OriginalTurnFailure>{if self.phase==Phase::Empty{return Ok(ActorFailureFetchStatus::Empty)}if self.phase==Phase::Closed{return Ok(ActorFailureFetchStatus::Closed)}self.permit(cx)?;Ok(if self.identity.is_some(){ActorFailureFetchStatus::Frozen}else{match self.phase{Phase::Publish|Phase::Read|Phase::ChunkAck|Phase::Ack=>ActorFailureFetchStatus::Action,Phase::Prepare=>ActorFailureFetchStatus::PrepareFault,Phase::Borrow=>ActorFailureFetchStatus::Page,Phase::Seal if self.sealed.is_some()=>ActorFailureFetchStatus::FinishSeal,Phase::Seal=>ActorFailureFetchStatus::SealFault,Phase::Deliver=>ActorFailureFetchStatus::Deliver,Phase::Recipient=>ActorFailureFetchStatus::Recipient,Phase::Complete=>ActorFailureFetchStatus::Complete,_=>return Err(refused().into())}})}
 pub fn finish_seal_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.permit(cx)?;if self.phase!=Phase::Seal||self.sealed.is_none(){return Err(refused().into())}if !pay_many(cx,1,size_of::<Phase>(),0)?{return Ok(false)}self.phase=Phase::Deliver;Ok(true)}
 pub fn plan_step(&self,cx:&StepContext<'_>)->Result<Option<ActorFailurePlan>,OriginalTurnFailure>{let permit=self.permit(cx)?;if self.identity.is_some()||self.captured.is_some(){return Ok(None)}let kind=match self.phase{Phase::Publish=>ActorFailureCallKind::PublishActorFailure,Phase::Read=>ActorFailureCallKind::ReadActorFailure,Phase::Borrow=>ActorFailureCallKind::BorrowActorFailure,Phase::ChunkAck=>ActorFailureCallKind::AcknowledgeActorFailureChunk,Phase::Ack=>ActorFailureCallKind::AcknowledgeActorFailure,_=>return Ok(None)};Ok(Some(plan(kind,permit.reference,self.offset,self.page)))}
 pub fn capture_frozen_step(&mut self,frozen:&GuestFrozenEscrowBorrow<'_>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let permit=self.permit(cx)?;frozen.validate_context(cx)?;let kind=match self.phase{Phase::Publish=>ActorFailureCallKind::PublishActorFailure,Phase::Read=>ActorFailureCallKind::ReadActorFailure,Phase::ChunkAck=>ActorFailureCallKind::AcknowledgeActorFailureChunk,Phase::Ack=>ActorFailureCallKind::AcknowledgeActorFailure,_=>return Err(refused().into())};if semio_plugin_host_guest_runtime::OwnedSemioExport::ALL.get(kind.tag()as usize-1).copied()!=Some(frozen.export())||frozen.recipient()!=permit.producer||frozen.header_len()!=184{return Err(refused().into())}if self.captured.is_some(){return if self.identity.as_ref().is_some_and(|identity|identity.matches(frozen)){Ok(true)}else{Err(refused().into())}}if let Some(identity)=self.identity.as_ref(){if !identity.matches(frozen){return Err(refused().into())}}else{if !pay_many(cx,1,size_of::<Option<GuestFrozenEscrowIdentity>>(),0)?{return Ok(false)}self.identity=Some(frozen.identity());return Ok(false)}if self.header_cursor<184{let word=frozen.header_word(self.header_cursor).ok_or_else(refused)?;if !pay_many(cx,2,word.len()+size_of::<usize>(),0)?{return Ok(false)}self.header[self.header_cursor..self.header_cursor+word.len()].copy_from_slice(word);self.header_cursor+=word.len();return Ok(false)}let(call,_)=ActorFailureFixedReceipt::read(&self.header)?;let permit=self.permit(cx)?;if call.reference!=permit.reference||!match(self.phase,call.status){(Phase::Publish,ActorFailureStatus::Publish{..})|(Phase::Read,ActorFailureStatus::Read{..})|(Phase::ChunkAck,ActorFailureStatus::AcknowledgeChunk{..})|(Phase::Ack,ActorFailureStatus::Acknowledge{..})=>true,_=>false}{return Err(refused().into())}if call.refusal.is_some(){return Err(refused().into())}if !pay_many(cx,1,size_of::<Option<ActorFailureCall>>(),0)?{return Ok(false)}self.captured=Some(call);Ok(true)}
 pub fn recipient_permit(&self)->Option<&ActorFailurePermit>{self.permit.as_ref()}
 pub fn original_reference(&self)->Option<&GuestActorFailureCallReference>{self.reference.as_ref()}
 pub fn settle_journaled_step(&mut self,view:&GuestJournaledReceipt<'_>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.permit(cx)?;let call=self.captured.as_ref().ok_or_else(refused)?;let actual=view.actor_call()?;if self.identity!=Some(view.identity())||actual.input!=call.input||actual.spent!=call.spent||actual.work_units_spent!=call.work_units_spent{return Err(refused().into())}if self.settled{return Ok(true)}if !pay_many(cx,1,size_of::<bool>(),0)?{return Ok(false)}self.settled=true;Ok(true)}
 pub fn header_returned_step(&mut self,proof:&GuestHeaderDeallocateReturned,acknowledgment:&mut Option<GuestActorFailureAcknowledged>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let permit=self.permit(cx)?;if !self.settled||!proof.proves(self.identity.as_ref().ok_or_else(refused)?,cx){return Err(refused().into())}let call=self.captured.ok_or_else(refused)?;let(mut phase,mut total,mut offset,mut page,mut cursor)=(self.phase,self.total,self.offset,self.page,self.cursor);let mut terminal=false;match call.status{ActorFailureStatus::Publish{outcome:Some(value)}=>{total=usize::try_from(value.byte_length).map_err(|_|refused())?;if total==0||total>semio_framework_job_payload::JOB_PAYLOAD_OPERATION_BYTES{return Err(refused().into())}phase=Phase::Prepare},ActorFailureStatus::Publish{outcome:None}=>{},ActorFailureStatus::Read{chunk:Some(value)}=>{if value.offset!=offset as u64{return Err(refused().into())}match value.byte_length{Some(length)=>{page=usize::try_from(length).map_err(|_|refused())?;if page==0||offset.checked_add(page).is_none_or(|end|end>total)||value.output_closed{return Err(refused().into())}cursor=0;phase=Phase::Borrow},None=>{if !value.output_closed||offset!=total{return Err(refused().into())}phase=Phase::Seal}}},ActorFailureStatus::Read{chunk:None}=>{},ActorFailureStatus::AcknowledgeChunk{acknowledged:true}=>{if cursor!=page{return Err(refused().into())}offset=offset.checked_add(page).ok_or_else(refused)?;page=0;cursor=0;phase=Phase::Read},ActorFailureStatus::AcknowledgeChunk{acknowledged:false}=>{},ActorFailureStatus::Acknowledge{acknowledged:true}=>{if self.accepted.as_ref().is_none_or(|accepted|!accepted.proves(permit,cx)){return Err(refused().into())}if acknowledgment.as_ref().ok_or_else(refused)?.reference_for(permit.producer,cx)?!=permit.reference{return Err(refused().into())}phase=Phase::Complete;terminal=true},ActorFailureStatus::Acknowledge{acknowledged:false}=>{},_=>return Err(refused().into())}let mut items=4;let mut bytes=size_of::<Option<ActorFailureCall>>()+size_of::<Option<GuestFrozenEscrowIdentity>>()+size_of::<usize>()+size_of::<bool>();if phase!=self.phase{items+=1;bytes+=size_of::<Phase>()}for changed in[total!=self.total,offset!=self.offset,page!=self.page,cursor!=self.cursor]{if changed{items+=1;bytes+=size_of::<usize>()}}if terminal{items+=2;bytes+=size_of::<Option<ActorFailureAcknowledged>>()+size_of::<Option<GuestActorFailureAcknowledged>>()}if !pay_many(cx,items,bytes,0)?{return Ok(false)}if terminal{self.acknowledged=Some(ActorFailureAcknowledged{proof:acknowledgment.take().unwrap()});}self.captured=None;self.identity=None;self.header_cursor=0;self.settled=false;self.phase=phase;self.total=total;self.offset=offset;self.page=page;self.cursor=cursor;Ok(true)}
 pub fn prepare_fault_step(&mut self,mut home:OriginalNativeBorrowed<'_,ActorFailureHome>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let permit=self.permit(cx)?;home.validate_context(cx)?;if self.phase!=Phase::Prepare||home.recipient_identity()!=permit.recipient{return Err(refused().into())}let value=home.value_mut();if !value.bind_step(permit.recipient,permit,cx)?||!value.prepare(permit,self.total,cx)?{return Ok(false)}if !pay_many(cx,1,size_of::<Phase>(),0)?{return Ok(false)}self.phase=Phase::Read;Ok(true)}
 pub fn copy_page_step(&mut self,runtime:&GuestRuntimes,instance:&GuestInstance,pointer:u32,length:usize,mut home:OriginalNativeBorrowed<'_,ActorFailureHome>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let permit=self.permit(cx)?;home.validate_context(cx)?;if self.phase!=Phase::Borrow||length!=self.page||home.recipient_identity()!=permit.recipient{return Err(refused().into())}let mut copied=false;let permit=self.permit.as_ref().ok_or_else(refused)?;let offset=self.offset;runtime.with_original_scalar_bytes(instance,pointer,length,cx,|bytes,cx|{copied=home.value_mut().append_page(permit,offset,bytes,&mut self.cursor,cx)?;Ok(())})?;if !copied{return Ok(false)}if !pay_many(cx,1,size_of::<Phase>(),0)?{return Ok(false)}self.phase=Phase::ChunkAck;Ok(true)}
 pub fn seal_fault_step(&mut self,mut home:OriginalNativeBorrowed<'_,ActorFailureHome>,fault:&mut Option<OriginalNativeLease<ActorFailureHome>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let permit=self.permit(cx)?;home.validate_context(cx)?;if self.phase!=Phase::Seal||home.recipient_identity()!=permit.recipient{return Err(refused().into())}if !home.value_mut().seal(permit,cx)?{return Ok(false)}let permit=self.permit.as_ref().ok_or_else(refused)?;if !super::seal_actor_failure_step(home,fault,permit,&mut self.sealed,cx)?{return Ok(false)}self.finish_seal_step(cx)}
 pub fn deliver_step(&mut self,recipient:&mut ActorFailureRecipient,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.permit(cx)?;if self.phase!=Phase::Deliver{return Err(refused().into())}if self.returned{if !pay_many(cx,1,size_of::<Phase>(),0)?{return Ok(false)}self.phase=Phase::Recipient;return Ok(true)}if !recipient.prepare_step(cx)?{return Ok(false)}if !self.acquired&&!recipient.lend_step(&mut self.donor,&mut self.acquired,cx)?{return Ok(false)}if self.capsule.is_none()&&self.sealed.is_some(){if !ActorFailureCapsule::take_sealed_into(&mut self.sealed,self.permit.as_ref().ok_or_else(refused)?,&mut self.capsule,cx)?{return Ok(false)}}let home=self.donor.as_mut().ok_or_else(refused)?;if self.capsule.is_some(){home.receive_step(&mut self.capsule,self.permit.as_ref().ok_or_else(refused)?,cx)?;return Ok(false)}recipient.return_home_step(&mut self.donor,&mut self.returned,cx)?;Ok(false)}
 pub fn accept_recipient_step(&mut self,proof:&mut Option<ActorFailureRecipientAccepted>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let permit=self.permit(cx)?;if self.phase!=Phase::Recipient||self.accepted.is_some()||self.donor.is_some()||!self.returned||proof.as_ref().is_none_or(|proof|!proof.proves(permit,cx)){return Err(refused().into())}let bytes=2*size_of::<Option<ActorFailureRecipientAccepted>>()+2*size_of::<bool>()+size_of::<Phase>();if !pay_many(cx,5,bytes,0)?{return Ok(false)}self.accepted=proof.take();self.acquired=false;self.returned=false;self.phase=Phase::Ack;Ok(true)}
 pub fn take_acknowledged_step(&mut self,out:&mut Option<ActorFailureAcknowledged>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.permit(cx)?;if self.phase!=Phase::Complete||out.is_some(){return Err(refused().into())}if self.acknowledged.is_none(){return Ok(false)}if !pay_many(cx,2,2*size_of::<Option<ActorFailureAcknowledged>>(),0)?{return Ok(false)}*out=self.acknowledged.take();Ok(true)}
 pub fn fault_recipient(&self)->Option<OriginalNativeRecipientIdentity>{self.permit.as_ref().map(|permit|permit.recipient)}
}
impl OriginalNativeRetirement for ActorFailureFetch{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}self.permit(cx)?;if self.phase!=Phase::Complete||self.capsule.is_some()||self.donor.is_some()||self.acquired||self.returned||self.captured.is_some()||self.identity.is_some(){return Err(refused().into())}let bytes=size_of::<Option<GuestActorFailureCallReference>>()+size_of::<Option<ActorFailurePermit>>()+size_of::<Option<ActorFailureSealed>>()+size_of::<Option<ActorFailureRecipientAccepted>>()+size_of::<Option<ActorFailureAcknowledged>>()+5*size_of::<usize>()+size_of::<Phase>();if !pay_many(cx,11,bytes,0)?{return Ok(false)}self.reference=None;self.permit=None;self.sealed=None;self.accepted=None;self.acknowledged=None;self.total=0;self.offset=0;self.page=0;self.cursor=0;self.home=0;self.phase=Phase::Closed;Ok(true)}fn terminal_is_empty(&self)->bool{matches!(self.phase,Phase::Empty|Phase::Closed)&&self.reference.is_none()&&self.permit.is_none()&&self.capsule.is_none()&&self.donor.is_none()&&!self.acquired&&!self.returned&&self.captured.is_none()&&self.identity.is_none()&&self.sealed.is_none()&&self.accepted.is_none()&&self.acknowledged.is_none()}}
impl Drop for ActorFailureFetch{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"ActorFailure fetch retains its actual Source, capsule and receipt owners until funded retirement")}}
#[cfg(test)]mod tests{use super::*;#[test]fn actual_failure_plan_matches_the_neutral_arity_cases(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🔣️.json")).unwrap();let reference=ActorFailureCallReference{failed_epoch:corpus["failedEpoch"].as_u64().unwrap(),call_kind:ActorFailureCallKind::from_tag(corpus["callKind"].as_u64().unwrap()).unwrap()};for row in corpus["plans"].as_array().unwrap(){let actual=plan(ActorFailureCallKind::from_tag(row["kind"].as_u64().unwrap()).unwrap(),reference,corpus["offset"].as_u64().unwrap()as usize,corpus["length"].as_u64().unwrap()as usize);assert_eq!(actual.scoped,row["scoped"].as_bool().unwrap());let expected=row["prefix"].as_array().unwrap();assert_eq!(actual.prefix_length,expected.len());for(i,v)in expected.iter().enumerate(){assert_eq!(actual.prefix[i],v.as_u64().unwrap())}assert_eq!(actual.prefix_length+if actual.scoped{19}else{2},row["arity"].as_u64().unwrap()as usize);}}}
